-- One-time operator-reviewed repair. Never run from application startup.
-- User confirmed: one matrix, Mariana/Gilvan, Cor/Capacidade, no real products.
BEGIN;
LOCK TABLE stores,users,stock_items IN SHARE ROW EXCLUSIVE MODE;
DO $$ BEGIN
 IF NOT EXISTS(SELECT 1 FROM stores s JOIN client_accounts a ON a.id=s.client_account_id WHERE s.id='STR-CELL-PONTO' AND a.id='PRT-MUM5YWBG8DSR' AND regexp_replace(a.document,'[^0-9]','','g')='38297104000182') THEN RAISE EXCEPTION 'Account identity mismatch'; END IF;
 IF EXISTS(SELECT 1 FROM stock_items WHERE store_id='STR-CELL-PONTO' AND id NOT IN ('STK-960a59274324fcad','STK-24769d4e91ef9181','STK-f5b7785d6914772d','STK-3487895380247313','STK-b31dbe896e9896a9','STK-ad449c50f6f6ff69','STK-CP-ACS-PEL3D','STK-CP-IPH14','STK-CP-CON-IPH12','STK-CP-IPH16P','STK-CP-IPH11','STK-CP-ACS-CABO1M','STK-CP-REDMI13P','STK-CP-IPH15','STK-CP-TEL-IPH13','STK-CP-BAT-IPH13','STK-CP-IPH15PM','STK-CP-IPH16PM','STK-CP-IPH13','STK-CP-IPH12','STK-CP-ACS-FONT20W','STK-CP-TEL-IPH14P','STK-CP-ACS-CAPACLR')) THEN RAISE EXCEPTION 'New products exist: review before cleanup'; END IF;
 IF EXISTS(SELECT 1 FROM stock_movements WHERE store_id='STR-CELL-PONTO') OR EXISTS(SELECT 1 FROM sales_order_lines l JOIN stock_items s ON s.id=COALESCE(l.stock_item_id,l.stock_id) WHERE s.store_id='STR-CELL-PONTO') OR EXISTS(SELECT 1 FROM stock_invoice_lines l JOIN stock_items s ON s.id=COALESCE(l.stock_item_id,l.stock_id) WHERE s.store_id='STR-CELL-PONTO') OR EXISTS(SELECT 1 FROM commercial_orders WHERE store_id='STR-CELL-PONTO') THEN RAISE EXCEPTION 'Business history exists: abort cleanup'; END IF;
END $$;
UPDATE client_accounts SET is_demo=true WHERE id='ACC-MARTHI-DEMO';
UPDATE stores s SET document=a.document,legal_name=a.legal_name,is_matrix=true,updated_at=now() FROM client_accounts a WHERE s.id='STR-CELL-PONTO' AND a.id=s.client_account_id;
UPDATE users SET active=false,session_version=session_version+1,updated_at=now() WHERE id='706cde99-34bb-4894-ab0f-d1818ab07103' AND client_account_id='PRT-MUM5YWBG8DSR';
UPDATE stores SET active=false,updated_at=now() WHERE id='STR-DEMO-02' AND client_account_id='ACC-MARTHI-DEMO';
UPDATE store_licenses SET status='cancelled',updated_at=now() WHERE store_id='STR-DEMO-02';
UPDATE product_attributes SET active=false WHERE store_id='STR-CELL-PONTO' AND id='ATTR-RET-CELLPONTO';
-- Rows have no real activity; non-secret snapshot retained before transaction.
DELETE FROM stock_item_variations WHERE store_id='STR-CELL-PONTO' AND stock_item_id IN ('STK-960a59274324fcad','STK-24769d4e91ef9181','STK-f5b7785d6914772d','STK-3487895380247313','STK-b31dbe896e9896a9','STK-ad449c50f6f6ff69','STK-CP-ACS-PEL3D','STK-CP-IPH14','STK-CP-CON-IPH12','STK-CP-IPH16P','STK-CP-IPH11','STK-CP-ACS-CABO1M','STK-CP-REDMI13P','STK-CP-IPH15','STK-CP-TEL-IPH13','STK-CP-BAT-IPH13','STK-CP-IPH15PM','STK-CP-IPH16PM','STK-CP-IPH13','STK-CP-IPH12','STK-CP-ACS-FONT20W','STK-CP-TEL-IPH14P','STK-CP-ACS-CAPACLR');
DELETE FROM stock_items WHERE store_id='STR-CELL-PONTO' AND id IN ('STK-960a59274324fcad','STK-24769d4e91ef9181','STK-f5b7785d6914772d','STK-3487895380247313','STK-b31dbe896e9896a9','STK-ad449c50f6f6ff69','STK-CP-ACS-PEL3D','STK-CP-IPH14','STK-CP-CON-IPH12','STK-CP-IPH16P','STK-CP-IPH11','STK-CP-ACS-CABO1M','STK-CP-REDMI13P','STK-CP-IPH15','STK-CP-TEL-IPH13','STK-CP-BAT-IPH13','STK-CP-IPH15PM','STK-CP-IPH16PM','STK-CP-IPH13','STK-CP-IPH12','STK-CP-ACS-FONT20W','STK-CP-TEL-IPH14P','STK-CP-ACS-CAPACLR');
